@app.websocket("/ws/notifications")
async def account_notification_feed(
    websocket: WebSocket,
    auth_user: AuthenticatedUser = Depends(get_authenticated_user_ws)
):
    await websocket.accept()
    try:
        while True:
            cmd = await websocket.receive_json()
            if cmd.get("action") == "listen_account":
                target_account = cmd.get("account_id")
                if target_account != auth_user.account_id:
                    await websocket.send_json({"error": "Unauthorized account subscription"})
                    continue
                await event_bus.attach_listener(target_account, websocket)
                await websocket.send_json({"attached": target_account})
    except WebSocketDisconnect:
        await event_bus.detach_all(websocket)
